import urllib.parse

class UrlStore:
    def __init__(self):
        self.urls = {}

    def add_url(self, url, tags):
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme in ["http", "https"]:
            self.urls[url] = tags

    def get_urls(self, tag):
        matching_urls = []
        for url, tags in self.urls.items():
            if tag in tags:
                matching_urls.append(url)
        return matching_urls

