import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse

allowed_domains = ['example.com']

def get_sitemap_urls(sitemap_url):
    response = requests.get(sitemap_url)
    soup = BeautifulSoup(response.text, 'html.parser')
    urls = [url.text for url in soup.find_all('loc')]
    return urls

def crawl(url):
    if not is_in_subdomain(url):
        return

    html = requests.get(url).text
    soup = BeautifulSoup(html, 'html.parser')

    for link in soup.find_all('a'):
        if is_in_subdomain(link.get('href')):
            crawl(link.get('href'))

def is_in_subdomain(url):
    parsed = urlparse(url)
    return parsed.scheme in ('http', 'https') and any(domain in parsed.netloc for domain in allowed_domains)

sitemap_urls = get_sitemap_urls('https://www.example.com/sitemap.xml')
for url in sitemap_urls:
    crawl(url)

