import os
from collections import defaultdict

def get_usage_by_ext_and_dir(path):
    usage = defaultdict(int)
    for root, dirs, files in os.walk(path):
        for d in dirs:
            for f in files:
                filepath = os.path.join(root, f)
                ext = os.path.splitext(f)[1]
                usage[(d, ext)] += os.path.getsize(filepath)

    return usage

if __name__ == '__main__':
    usage = get_usage_by_ext_and_dir('/var/www/html')
    for (dir, ext), size in usage.items():
        print(f'{ext} files in {dir}: {size} bytes')

